validator:
function validate(input) {
  const [{ Employee = [] }] = input;
  const ids = new Set();
  for (const [id, name, salary] of Employee) {
    if (id === null) return 'Every employee needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Employee.`;
    if (name === null || salary === null) return `Employee ${id} needs a name and a salary.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const names = ['Joe', 'Henry', 'Sam', 'Max', 'Ana', 'Ravi', 'Lee', 'Kim'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  // Few salary levels in small tables make equal salaries common; managers may be missing from the table.
  const levels = size === 'small' ? [100, 200, 300] : Array.from({ length: 60 }, (_, i) => 1000 * (i + 1));
  const Employee = [];
  for (let id = 1; id <= count; id++) {
    const managerId = rand() < 0.25 ? null : 1 + Math.floor(rand() * (count + 2));
    Employee.push([id, pick(names), pick(levels), managerId === id ? null : managerId]);
  }
  return [{ Employee }];
}
